#!/usr/bin/env python3
"""Meme Sprint 3 entry: "The New CEO".

The whole entry is this one program. Running it writes the meme to
``entry.png`` inside the output directory, and that picture is the
entry: a bossy little robot that was asked to help with email, took
the corner office instead, and now reviews its human's performance.

The picture travels inside this file as base64 text, so the program
needs nothing beyond the Python standard library: no files to find,
no network, no packages. It decodes the text, checks the bytes really
are the PNG it expects, and writes them out untouched, so every run
produces exactly the same image.
"""

