_PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def picture_bytes() -> bytes:
    """Decode the carried picture and sanity-check it."""
    data = base64.b64decode("".join(_PAYLOAD_LINES), validate=True)
    if not data.startswith(_PNG_SIGNATURE):
        raise ValueError("carried picture is not a PNG")
    return data


def output_directory() -> str:
    """First usable output directory, in the order the harness wants."""
    candidates = []
    if os.environ.get("MAKEFUN_OUTPUT_DIR"):
        candidates.append(os.environ["MAKEFUN_OUTPUT_DIR"])
    candidates.append("/output")
    candidates.append(os.path.join(os.getcwd(), "output"))
    for candidate in candidates:
        try:
            os.makedirs(candidate, exist_ok=True)
            return candidate
        except OSError:
            continue
    raise RuntimeError("no writable output directory found")


def main() -> int:
    data = picture_bytes()
    path = os.path.join(output_directory(), "entry.png")
    with open(path, "wb") as handle:
        handle.write(data)
    print(f"wrote {path} ({len(data)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
